head.b:skin:
/* ===== REPLACE-ZONE: brand colors (from logo: royal blue + red on deep navy) ===== */
:root{
  --navy:#050d24; --navy2:#0a1b45; --blue:#1f5bff; --blue2:#0f3fd0; --sky:#eaf1ff;
  --red:#e3202e; --red2:#ff4757; --ink:#0e1a35; --muted:#55627e; --line:#dce5f6;
  --white:#ffffff; --r:18px; --shadow:0 16px 44px rgba(9,30,90,.14);
  --grad:linear-gradient(135deg,#1f5bff 0%,#0f3fd0 55%,#e3202e 130%);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:96px;-webkit-text-size-adjust:100%}
body{margin:0;font-family:"Segoe UI",system-ui,-apple-system,Roboto,"Helvetica Neue",Arial,sans-serif;color:var(--ink);background:#f5f8ff;line-height:1.72;overflow-x:hidden;font-size:17px}
body.lock{overflow:hidden}
img{max-width:100%;height:auto;display:block}
a{color:var(--blue2);text-decoration:none;transition:color .2s}
a:hover{color:var(--red)}
h1,h2,h3,h4{line-height:1.2;margin:0 0 .5em;color:var(--navy);letter-spacing:-.01em}
p{margin:0 0 1em}
ul{margin:0;padding:0;list-style:none}
.container{width:min(1180px,92%);margin:0 auto}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}

/* progress bar */
#prog{position:fixed;top:0;left:0;height:4px;width:0;background:linear-gradient(90deg,var(--blue),var(--red));z-index:1200;transition:width .1s}

/* top bar */
.topbar{background:#030918;color:#c9d6f5;font-size:14px}
.topbar .container{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:8px 0;flex-wrap:wrap}
.topbar a{color:#fff;font-weight:600}
.topbar a:hover{color:#ff7a85}
.topbar .tb-l,.topbar .tb-r{display:flex;gap:20px;align-items:center;flex-wrap:wrap}

/* header */
.site-header{position:sticky;top:0;z-index:1000;background:rgba(5,13,36,.94);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);border-bottom:1px solid rgba(255,255,255,.08);transition:box-shadow .3s}
.site-header.scrolled{box-shadow:0 10px 30px rgba(0,0,0,.35)}
.head-in{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:10px 0}
.brand{display:flex;align-items:center;gap:12px;color:#fff}
.brand img{height:58px;width:auto;border-radius:12px;background:#000}
.brand .bn{display:block;font-weight:800;font-size:19px;line-height:1.1;letter-spacing:.02em;color:#fff}
.brand .bs{display:block;font-size:12px;letter-spacing:.2em;text-transform:uppercase;color:#ff7a85;font-weight:700}
.brand:hover{color:#fff}
.nav{display:flex;align-items:center}
.menu{display:flex;align-items:center;gap:4px}
.menu>li{position:relative}
.menu>li>a{display:block;padding:10px 15px;color:#e8efff;font-weight:600;font-size:16px;border-radius:10px;position:relative}
.menu>li>a:after{content:"";position:absolute;left:15px;right:15px;bottom:5px;height:2px;background:linear-gradient(90deg,var(--blue),var(--red));transform:scaleX(0);transform-origin:left;transition:transform .3s}
.menu>li>a:hover{color:#fff}
.menu>li>a:hover:after{transform:scaleX(1)}
.has-sub>a{padding-right:4px!important}
.sub-toggle{background:none;border:0;color:#e8efff;cursor:pointer;padding:10px 10px 10px 0;display:inline-flex;align-items:center;vertical-align:middle;position:absolute;right:-6px;top:0;height:100%}
.has-sub{padding-right:20px}
.sub-toggle svg{width:14px;height:14px;transition:transform .3s}
.has-sub.open .sub-toggle svg{transform:rotate(180deg)}
.sub{position:absolute;top:100%;left:0;min-width:300px;background:#fff;border-radius:14px;box-shadow:0 22px 50px rgba(5,13,36,.35);padding:10px;opacity:0;visibility:hidden;transform:translateY(12px);transition:all .25s;border-top:3px solid var(--red)}
.sub li a{display:block;padding:12px 14px;border-radius:10px;color:var(--navy);font-weight:600;font-size:15.5px}
.sub li a:hover{background:var(--sky);color:var(--blue2);padding-left:20px}
.sub li a{transition:all .2s}
.has-sub.open>.sub,.has-sub:focus-within>.sub{opacity:1;visibility:visible;transform:none}
@media (hover:hover) and (min-width:981px){.has-sub:hover>.sub{opacity:1;visibility:visible;transform:none}}
.m-only{display:none}
.btn{display:inline-flex;align-items:center;gap:9px;padding:14px 26px;border-radius:50px;font-weight:700;font-size:16px;border:2px solid transparent;cursor:pointer;transition:transform .25s,box-shadow .25s,background .25s;line-height:1.2;text-align:center;justify-content:center}
.btn:hover{transform:translateY(-3px)}
.btn svg{width:18px;height:18px;flex:none}
.btn-red{background:linear-gradient(135deg,#ff4757,#e3202e);color:#fff;box-shadow:0 10px 26px rgba(227,32,46,.4)}
.btn-red:hover{color:#fff;box-shadow:0 16px 34px rgba(227,32,46,.55)}
.btn-blue{background:var(--grad);color:#fff;box-shadow:0 10px 26px rgba(31,91,255,.4)}
.btn-blue:hover{color:#fff}
.btn-ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.45)}
.btn-ghost:hover{background:#fff;color:var(--navy)}
.btn-line{background:#fff;color:var(--blue2);border-color:var(--blue)}
.btn-line:hover{background:var(--blue);color:#fff}
.pulse{animation:pulse 2.4s infinite}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(227,32,46,.6)}70%{box-shadow:0 0 0 16px rgba(227,32,46,0)}100%{box-shadow:0 0 0 0 rgba(227,32,46,0)}}
.head-cta{padding:12px 22px}
.nav-toggle{display:none;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.2);border-radius:12px;width:48px;height:48px;cursor:pointer;padding:0;position:relative}
.nav-toggle span{position:absolute;left:12px;right:12px;height:2px;background:#fff;border-radius:2px;transition:all .3s}
.nav-toggle span:nth-child(1){top:16px}.nav-toggle span:nth-child(2){top:23px}.nav-toggle span:nth-child(3){top:30px}
.nav-toggle.active span:nth-child(1){top:23px;transform:rotate(45deg)}
.nav-toggle.active span:nth-child(2){opacity:0}
.nav-toggle.active span:nth-child(3){top:23px;transform:rotate(-45deg)}
.overlay{position:fixed;inset:0;background:rgba(3,9,24,.65);opacity:0;visibility:hidden;transition:.3s;z-index:1001}
.overlay.show{opacity:1;visibility:visible}

/* hero */
.hero{position:relative;background:linear-gradient(120deg,#050d24,#0a1b45 55%,#0f2a78);background-size:200% 200%;animation:bgshift 16s ease infinite;color:#fff;padding:78px 0 150px;overflow:hidden}
@keyframes bgshift{0%{background-position:0 50%}50%{background-position:100% 50%}100%{background-position:0 50%}}
.orb{position:absolute;border-radius:50%;filter:blur(70px);opacity:.45;animation:floaty 12s ease-in-out infinite}
.o1{width:380px;height:380px;background:var(--blue);top:-120px;left:-80px}
.o2{width:320px;height:320px;background:var(--red);bottom:20px;right:-60px;animation-delay:-5s;opacity:.3}
@keyframes floaty{0%,100%{transform:translate(0,0)}50%{transform:translate(40px,30px)}}
.air{position:absolute;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.55),transparent);opacity:.5;animation:blow 6s linear infinite}
.air.a1{top:22%;width:40%;animation-duration:7s}
.air.a2{top:48%;width:30%;animation-duration:5s;animation-delay:-2s}
.air.a3{top:70%;width:46%;animation-duration:9s;animation-delay:-4s}
@keyframes blow{0%{transform:translateX(-60%)}100%{transform:translateX(280%)}}
.hero-grid{position:relative;display:grid;grid-template-columns:1.05fr .95fr;gap:50px;align-items:center}
.badge{display:inline-flex;align-items:center;gap:10px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);padding:8px 18px;border-radius:50px;font-size:14px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;margin-bottom:22px}
.dot{width:10px;height:10px;border-radius:50%;background:#35e08a;display:inline-block;animation:pulsegreen 2s infinite}
@keyframes pulsegreen{0%{box-shadow:0 0 0 0 rgba(53,224,138,.7)}100%{box-shadow:0 0 0 12px rgba(53,224,138,0)}}
.hero h1{color:#fff;font-size:clamp(34px,5vw,58px);font-weight:800;margin-bottom:20px}
.hero h1 span{background:linear-gradient(90deg,#7fa6ff,#ff6b78);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent}
.hero .lead{font-size:19px;color:#cfdcff;max-width:560px}
.hero-btns{display:flex;flex-wrap:wrap;gap:14px;margin:28px 0 30px}
.chips{display:flex;flex-wrap:wrap;gap:10px}
.chips a{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.2);color:#e6eeff;padding:7px 16px;border-radius:50px;font-size:14px;font-weight:600}
.chips a:hover{background:#fff;color:var(--navy)}
.hero-vis{position:relative}
.hero-vis .frame{border-radius:28px;padding:6px;background:linear-gradient(135deg,var(--blue),var(--red));box-shadow:0 30px 70px rgba(0,0,0,.5);animation:floaty2 7s ease-in-out infinite}
.hero-vis img{border-radius:23px;width:100%;aspect-ratio:4/3;object-fit:cover}
@keyframes floaty2{0%,100%{transform:translateY(0)}50%{transform:translateY(-14px)}}
.fcard{position:absolute;background:#fff;color:var(--navy);padding:12px 18px;border-radius:14px;box-shadow:var(--shadow);font-weight:700;font-size:14.5px;display:flex;align-items:center;gap:10px;line-height:1.3}
.fcard b{display:block;font-size:12px;color:var(--muted);font-weight:600}
.fcard i{width:38px;height:38px;border-radius:50%;background:var(--grad);display:grid;place-items:center;color:#fff;font-style:normal;flex:none}
.fc1{left:-26px;bottom:34px;animation:floaty2 6s ease-in-out infinite}
.fc2{right:-14px;top:26px;animation:floaty2 8s ease-in-out infinite;animation-delay:-3s}
.waves{position:absolute;left:0;right:0;bottom:-1px;height:120px;overflow:hidden;line-height:0}
.waves svg{position:absolute;bottom:0;left:0;width:200%;height:100%;animation:slide 18s linear infinite}
.waves svg.w2{animation-duration:28s;animation-direction:reverse;opacity:.55}
@keyframes slide{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* sections */
.sec{padding:84px 0;position:relative}
.sec.alt{background:#fff}
.sec.dark{background:linear-gradient(135deg,#050d24,#0a1b45);color:#d6e1ff}
.sec.dark h2,.sec.dark h3{color:#fff}
.sec-head{max-width:780px;margin:0 auto 48px;text-align:center}
.eyebrow{display:inline-block;color:var(--red);font-weight:800;font-size:13.5px;letter-spacing:.16em;text-transform:uppercase;margin-bottom:10px}
.dark .eyebrow{color:#ff7a85}
.sec-head h2{font-size:clamp(28px,3.6vw,42px);font-weight:800;position:relative;padding-bottom:18px}
.sec-head h2:after{content:"";position:absolute;left:50%;bottom:0;width:70px;height:4px;margin-left:-35px;border-radius:4px;background:linear-gradient(90deg,var(--blue),var(--red));animation:grow 2.6s ease-in-out infinite alternate}
@keyframes grow{from{width:44px;margin-left:-22px}to{width:96px;margin-left:-48px}}
.sec-head p{color:var(--muted);font-size:18px;margin:6px 0 0}
.dark .sec-head p{color:#b9c9f3}
.grid2,.grid3,.grid4{display:grid;gap:26px}
.grid2{grid-template-columns:repeat(2,1fr)}
.grid3{grid-template-columns:repeat(3,1fr)}
.grid4{grid-template-columns:repeat(4,1fr)}
.card{background:#fff;border:1px solid var(--line);border-radius:var(--r);padding:30px 28px;box-shadow:0 6px 22px rgba(9,30,90,.06);transition:transform .35s,box-shadow .35s,border-color .35s;position:relative;overflow:hidden}
.card:before{content:"";position:absolute;left:0;top:0;height:4px;width:100%;background:linear-gradient(90deg,var(--blue),var(--red));transform:scaleX(0);transform-origin:left;transition:transform .45s}
.card:hover{transform:translateY(-8px);box-shadow:var(--shadow);border-color:#bcd0ff}
.card:hover:before{transform:scaleX(1)}
.card h3{font-size:21px}
.card p{color:var(--muted);font-size:16.5px}
.card p:last-child{margin-bottom:0}
.num{width:50px;height:50px;border-radius:14px;background:var(--grad);color:#fff;display:grid;place-items:center;font-weight:800;font-size:18px;margin-bottom:18px;transition:transform .4s}
.card:hover .num{transform:rotate(-8deg) scale(1.1)}
.dark .card{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.14);box-shadow:none}
.dark .card h3{color:#fff}
.dark .card p{color:#c1d0f5}

/* intro */
.split{display:grid;grid-template-columns:.9fr 1.1fr;gap:56px;align-items:center}
.split .pic{position:relative}
.split .pic img{border-radius:24px;box-shadow:var(--shadow);width:100%;aspect-ratio:4/3;object-fit:cover}
.split .pic:before{content:"";position:absolute;inset:-14px 14px 14px -14px;border-radius:26px;border:3px solid var(--blue);z-index:-1;animation:floaty2 8s ease-in-out infinite}
.split .pic{z-index:1}
.split h2{font-size:clamp(27px,3.4vw,40px);font-weight:800}
.split p{color:var(--muted)}

/* service cards */
.svc{background:#fff;border-radius:22px;overflow:hidden;border:1px solid var(--line);box-shadow:0 8px 26px rgba(9,30,90,.08);transition:transform .4s,box-shadow .4s;display:flex;flex-direction:column}
.svc:hover{transform:translateY(-10px);box-shadow:0 26px 56px rgba(9,30,90,.2)}
.svc .im{overflow:hidden;position:relative}
.svc img{width:100%;aspect-ratio:16/11;object-fit:cover;transition:transform .7s}
.svc:hover img{transform:scale(1.1)}
.svc .im:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(5,13,36,.55))}
.svc .bd{padding:26px 26px 28px;display:flex;flex-direction:column;flex:1}
.svc h3{font-size:22px}
.svc h3 a{color:var(--navy)}
.svc h3 a:hover{color:var(--red)}
.svc p{color:var(--muted);font-size:16.5px;flex:1}
.more{font-weight:800;display:inline-flex;gap:8px;align-items:center;color:var(--blue2)}
.more:after{content:"\2192";transition:transform .25s}
.more:hover:after{transform:translateX(7px)}

/* steps (install) */
.steps{counter-reset:s;display:grid;gap:22px;grid-template-columns:repeat(3,1fr)}
.step{background:#fff;border-radius:var(--r);padding:34px 28px 28px;border:1px solid var(--line);position:relative;transition:transform .35s,box-shadow .35s}
.step:hover{transform:translateY(-8px);box-shadow:var(--shadow)}
.step:before{counter-increment:s;content:counter(s);position:absolute;top:-20px;left:24px;width:44px;height:44px;border-radius:50%;background:var(--grad);color:#fff;font-weight:800;display:grid;place-items:center;box-shadow:0 8px 20px rgba(31,91,255,.4)}
.step h3{font-size:21px}
.step p{color:var(--muted);font-size:16.5px}
.lead-in{max-width:860px;margin:0 auto 44px;text-align:center;color:var(--muted);font-size:18px}
.link-row{text-align:center;margin-top:38px}

/* faq */
.faq{max-width:900px;margin:0 auto;display:grid;gap:14px}
.faq details{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden;transition:box-shadow .3s,border-color .3s}
.faq details[open]{box-shadow:var(--shadow);border-color:#b8ccff}
.faq summary{cursor:pointer;list-style:none;padding:20px 60px 20px 24px;font-weight:700;font-size:18px;color:var(--navy);position:relative}
.faq summary::-webkit-details-marker{display:none}
.faq summary:after{content:"+";position:absolute;right:20px;top:50%;margin-top:-17px;width:34px;height:34px;border-radius:50%;background:var(--sky);color:var(--blue2);display:grid;place-items:center;font-size:22px;font-weight:700;transition:transform .3s,background .3s}
.faq details[open] summary:after{content:"\2212";background:var(--red);color:#fff;transform:rotate(180deg)}
.faq details p{padding:0 24px 22px;margin:0;color:var(--muted);animation:fadeIn .4s}
@keyframes fadeIn{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}

/* location */
.loc{display:grid;grid-template-columns:.8fr 1.2fr;gap:30px;align-items:stretch}
.loc.no-map{grid-template-columns:1fr;max-width:760px;margin:0 auto}
.info{background:linear-gradient(135deg,#050d24,#0a1b45);color:#d6e1ff;border-radius:24px;padding:36px 32px}
.info h3{color:#fff;font-size:24px}
.info li{display:flex;gap:14px;align-items:flex-start;padding:14px 0;border-bottom:1px solid rgba(255,255,255,.1)}
.info li:last-child{border:0}
.info .ic{width:44px;height:44px;border-radius:12px;background:var(--grad);display:grid;place-items:center;flex:none}
.info .ic svg{width:20px;height:20px;fill:#fff}
.info small{display:block;color:#8fa6e0;font-size:13px;letter-spacing:.08em;text-transform:uppercase}
.info a{color:#fff;font-weight:700}
.info a:hover{color:#ff7a85}
.map-frame{border-radius:24px;overflow:hidden;box-shadow:var(--shadow);min-height:380px;background:#dfe8fb;position:relative}
.map-frame iframe{position:absolute;inset:0;width:100%;height:100%;border:0;max-width:100%}

/* CTA */
.cta{background:var(--grad);color:#fff;padding:80px 0;position:relative;overflow:hidden;text-align:center}
.cta:before,.cta:after{content:"";position:absolute;width:420px;height:420px;border-radius:50%;background:rgba(255,255,255,.08);animation:floaty 14s ease-in-out infinite}
.cta:before{top:-200px;left:-120px}.cta:after{bottom:-220px;right:-100px;animation-delay:-6s}
.cta .container{position:relative;z-index:1;max-width:860px}
.cta h2{color:#fff;font-size:clamp(28px,4vw,44px);font-weight:800}
.cta p{font-size:18.5px;color:#e7eeff}
.cta .hero-btns{justify-content:center}
.btn-white{background:#fff;color:var(--blue2)}
.btn-white:hover{color:var(--red)}

/* footer */
.site-footer{background:#030918;color:#aab9de;padding:70px 0 0;position:relative}
.site-footer:before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg,var(--blue),var(--red),var(--blue));background-size:200% 100%;animation:bgshift 6s linear infinite}
.f-grid{display:grid;grid-template-columns:1.4fr 1fr 1.2fr 1fr 1.2fr;gap:36px}
.site-footer h4{color:#fff;font-size:17px;margin-bottom:18px;position:relative;padding-bottom:10px}
.site-footer h4:after{content:"";position:absolute;left:0;bottom:0;width:34px;height:3px;border-radius:3px;background:var(--red)}
.site-footer li{margin-bottom:10px}
.site-footer a{color:#aab9de}
.site-footer a:hover{color:#fff;padding-left:4px}
.f-brand img{height:70px;width:auto;border-radius:12px;margin-bottom:14px;background:#000}
.f-brand p{font-size:15.5px}
.f-bottom{margin-top:50px;border-top:1px solid rgba(255,255,255,.1);padding:22px 0;text-align:center;font-size:14.5px}

/* floating call (mobile) */
.fab{display:none;position:fixed;right:16px;bottom:16px;z-index:900;width:60px;height:60px;border-radius:50%;background:linear-gradient(135deg,#ff4757,#e3202e);color:#fff;place-items:center;box-shadow:0 10px 26px rgba(227,32,46,.55);animation:pulse 2.4s infinite}
.fab svg{width:26px;height:26px;fill:#fff}

/* blog + posts + pages */
.blog-sec{padding:84px 0;background:#f5f8ff}
.page-wrap{padding:60px 0 80px}
.post-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.post-card{background:#fff;border-radius:20px;overflow:hidden;border:1px solid var(--line);box-shadow:0 8px 24px rgba(9,30,90,.07);transition:transform .35s,box-shadow .35s;display:flex;flex-direction:column}
.post-card:hover{transform:translateY(-8px);box-shadow:var(--shadow)}
.pc-img{display:block;overflow:hidden;aspect-ratio:16/10;background:var(--grad)}
.pc-img img{width:100%;height:100%;object-fit:cover;transition:transform .6s}
.post-card:hover .pc-img img{transform:scale(1.08)}
.pc-img.noimg{display:grid;place-items:center;color:#fff;font-size:54px}
.pc-body{padding:22px 24px 26px;display:flex;flex-direction:column;flex:1}
.pc-meta{font-size:13.5px;color:var(--muted);margin-bottom:8px;display:flex;gap:12px;flex-wrap:wrap}
.pc-body h3{font-size:20px}
.pc-body h3 a{color:var(--navy)}
.pc-body h3 a:hover{color:var(--red)}
.pc-body p{color:var(--muted);font-size:16px;flex:1}
.pc-src{display:none}
.empty-state{display:none;text-align:center;background:#fff;border:2px dashed #b9cbf5;border-radius:20px;padding:46px 24px;color:var(--muted);max-width:720px;margin:0 auto}
.pager{display:flex;justify-content:space-between;gap:12px;margin-top:40px;flex-wrap:wrap}
.entry{background:#fff;border-radius:24px;padding:clamp(24px,5vw,56px);box-shadow:var(--shadow);border:1px solid var(--line);max-width:900px;margin:0 auto}
.entry h1{font-size:clamp(28px,4vw,44px);font-weight:800}
.entry .meta{display:flex;flex-wrap:wrap;gap:8px 18px;color:var(--muted);font-size:15px;margin-bottom:22px;padding-bottom:18px;border-bottom:1px solid var(--line)}
.entry .labels a{background:var(--sky);color:var(--blue2);padding:3px 12px;border-radius:50px;font-size:13.5px;font-weight:700;margin-right:6px}
.entry .labels a:hover{background:var(--blue);color:#fff}
.entry .feat{margin:0 0 26px}
.entry .feat img{border-radius:18px;width:100%;max-height:460px;object-fit:cover}
.entry-body{overflow-wrap:anywhere;font-size:18px}
.entry-body img{border-radius:12px;max-width:100%;height:auto}
.entry-body h2,.entry-body h3{margin-top:1.6em}
.entry-body iframe,.entry-body table{max-width:100%}
.entry-body table{display:block;overflow-x:auto}
.entry-body blockquote{border-left:4px solid var(--red);margin:1.4em 0;padding:6px 20px;background:var(--sky);border-radius:0 12px 12px 0}
.entry-body a{text-decoration:underline}
.share{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:30px;padding-top:22px;border-top:1px solid var(--line);font-weight:700}
.share a{background:var(--navy);color:#fff;padding:8px 18px;border-radius:50px;font-size:14.5px}
.share a:hover{background:var(--red);color:#fff}
.notfound{text-align:center;padding:60px 20px}

/* reveal animations */
.js .reveal{opacity:0;transform:translateY(32px);transition:opacity .8s ease,transform .8s ease;transition-delay:var(--d,0s)}
.js .reveal.in{opacity:1;transform:none}

/* responsive */
@media (max-width:1100px){.f-grid{grid-template-columns:1fr 1fr 1fr}.grid4{grid-template-columns:repeat(2,1fr)}}
@media (max-width:980px){
  .nav-toggle{display:block}
  .head-cta{display:none}
  .m-only{display:block}
  .nav{position:fixed;top:0;right:0;bottom:0;width:min(88%,380px);background:#07122e;z-index:1002;transform:translateX(100%);transition:transform .35s;padding:84px 22px 30px;overflow-y:auto;align-items:flex-start;box-shadow:-20px 0 50px rgba(0,0,0,.5)}
  .nav.open{transform:none}
  .nav-toggle{z-index:1003;position:relative}
  .menu{flex-direction:column;align-items:stretch;width:100%;gap:2px}
  .menu>li>a{padding:15px 12px;font-size:18px;border-bottom:1px solid rgba(255,255,255,.08);border-radius:0}
  .menu>li>a:after{display:none}
  .has-sub{padding-right:0}
  .has-sub>a{padding-right:56px!important}
  .sub-toggle{right:0;width:52px;height:56px;padding:0;justify-content:center;border-left:1px solid rgba(255,255,255,.08)}
  .sub{position:static;min-width:0;opacity:1;visibility:visible;transform:none;box-shadow:none;background:rgba(255,255,255,.05);max-height:0;overflow:hidden;padding:0 8px;border-top:0;border-radius:0 0 12px 12px;transition:max-height .4s,padding .3s}
  .has-sub.open>.sub{max-height:420px;padding:8px}
  .sub li a{color:#dbe6ff;font-size:16px;padding:12px}
  .sub li a:hover{background:rgba(255,255,255,.08);color:#fff}
  .m-only{margin-top:18px}
  .m-only .btn{width:100%}
  .hero{padding:56px 0 130px}
  .hero-grid,.split,.loc{grid-template-columns:1fr}
  .hero-vis{max-width:560px;margin:10px auto 0}
  .grid3,.post-grid,.steps{grid-template-columns:repeat(2,1fr)}
  .steps{row-gap:40px}
  .fab{display:grid}
  .split .pic:before{display:none}
}
@media (max-width:640px){
  body{font-size:16.5px}
  .sec,.blog-sec{padding:60px 0}
  .grid2,.grid3,.grid4,.post-grid,.steps{grid-template-columns:1fr}
  .topbar .tb-r{display:none}
  .brand img{height:50px}
  .brand .bn{font-size:16px}.brand .bs{font-size:10px}
  .f-grid{grid-template-columns:1fr 1fr}
  .f-brand{grid-column:1/-1}
  .fc1{left:6px}.fc2{right:6px}
  .hero-btns .btn{width:100%}
  .btn{padding:14px 20px}
  .card,.step{padding:26px 22px}
}
@media (max-width:420px){.f-grid{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.js .reveal{opacity:1;transform:none}}

body.script:
//
(function(){
  var d = document;
  function q(s){ return Array.prototype.slice.call(d.querySelectorAll(s)); }

  /* mobile menu */
  var nav = d.getElementById('nav'), tg = d.getElementById('navToggle'), ov = d.getElementById('navOverlay');
  function setNav(o){
    nav.classList.toggle('open', o);
    ov.classList.toggle('show', o);
    tg.classList.toggle('active', o);
    tg.setAttribute('aria-expanded', o ? 'true' : 'false');
    d.body.classList.toggle('lock', o);
  }
  tg.addEventListener('click', function(){ setNav(!nav.classList.contains('open')); });
  ov.addEventListener('click', function(){ setNav(false); });

  /* services dropdown (click for touch + keyboard; hover handled in CSS on desktop) */
  function closeSubs(){
    q('.has-sub').forEach(function(li){
      li.classList.remove('open');
      li.querySelector('.sub-toggle').setAttribute('aria-expanded', 'false');
    });
  }
  q('.sub-toggle').forEach(function(b){
    b.addEventListener('click', function(e){
      e.preventDefault(); e.stopPropagation();
      var li = b.parentNode, open = !li.classList.contains('open');
      closeSubs();
      li.classList.toggle('open', open);
      b.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  });
  d.addEventListener('click', function(e){
    if (!e.target.closest('.has-sub')) { closeSubs(); }
  });
  d.addEventListener('keydown', function(e){
    if (e.key === 'Escape') { setNav(false); closeSubs(); }
  });
  q('#nav a').forEach(function(a){ a.addEventListener('click', function(){ setNav(false); }); });

  /* scroll progress + header shadow */
  var bar = d.getElementById('prog'), hd = d.getElementById('siteHeader');
  function onScroll(){
    var h = d.documentElement, max = h.scrollHeight - h.clientHeight;
    bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + '%';
    hd.classList.toggle('scrolled', h.scrollTop > 20);
  }
  window.addEventListener('scroll', onScroll, {passive:true}); onScroll();

  /* reveal on scroll */
  var rv = q('.reveal');
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function(es){
      es.forEach(function(x){ if (x.isIntersecting) { x.target.classList.add('in'); io.unobserve(x.target); } });
    }, {threshold: 0.12});
    rv.forEach(function(el){ io.observe(el); });
  } else { rv.forEach(function(el){ el.classList.add('in'); }); }

  /* footer year */
  var y = d.getElementById('yr'); if (y) { y.textContent = new Date().getFullYear(); }

  /* blog: empty state + snippet fallback */
  q('.pc-src').forEach(function(s){
    var t = (s.textContent || '').replace(/\s+/g, ' ').trim();
    if (t.length > 150) { t = t.substring(0, 150).replace(/\s+\S*$/, '') + '...'; }
    var p = d.createElement('p'); p.textContent = t; s.parentNode.insertBefore(p, s);
  });
  var grid = d.getElementById('postGrid'), empty = d.getElementById('emptyState');
  if (grid && empty && grid.querySelectorAll('.post-card').length === 0) {
    grid.style.display = 'none'; empty.style.display = 'block';
  }

  /* post page: hide featured image if body already starts with the same image */
  var feat = d.getElementById('featImg'), body = d.getElementById('postBody');
  if (feat && body) {
    var fi = feat.querySelector('img'), bi = body.querySelector('img');
    if (fi && bi) {
      var nm = function(u){ return (u || '').split('?')[0].split('/').pop(); };
      if (nm(fi.src) === nm(bi.src)) { feat.style.display = 'none'; }
    }
  }

  /* map: if no iframe pasted, hide frame and center the contact card */
  var mf = d.getElementById('mapFrame'), lg = d.getElementById('locGrid');
  if (mf && lg && !mf.querySelector('iframe')) { mf.style.display = 'none'; lg.classList.add('no-map'); }
})();
//
